fn pad2(x: i32, y: i32, v: i32, rgb: i32, sc: i32) {
    if v < 10 {
        host::display::draw_number(x, y, 0, rgb, sc);
        host::display::draw_number(x + sc * 8, y, v, rgb, sc);
    } else {
        host::display::draw_number(x, y, v, rgb, sc);
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(2);
    let mut run: i32 = host::display::state_get(0);
    let mut f: i32 = host::display::state_get(1);
    let mut laps: i32 = host::display::state_get(3);
    if down == 1 && prev == 0 {
        if host::display::pointer_x() < w / 2 {
            run = 1 - run;
        } else {
            if run == 1 && laps < 4 {
                host::display::state_set(10 + laps, f);
                laps = laps + 1;
            }
        }
    }
    if run == 1 { f = f + 1; }
    host::display::state_set(0, run);
    host::display::state_set(1, f);
    host::display::state_set(2, down);
    host::display::state_set(3, laps);
    host::display::clear(0x000000);
    host::display::draw_string(8, 8, "STOPWATCH", 0x808080, 1);
    let col: i32 = if run == 1 { 0x00ff80 } else { 0xffffff };
    pad2(8, 28, f / 60, col, 4);
    host::display::fill_rect(74, 52, 4, 4, col);
    pad2(84, 28, (f % 60) * 100 / 60, col, 4);
    let mut i: i32 = 0;
    while i < laps {
        let lf: i32 = host::display::state_get(10 + i);
        let y: i32 = 90 + i * 22;
        host::display::draw_string(8, y, "LAP", 0x808080, 1);
        host::display::draw_number(40, y, i + 1, 0x808080, 1);
        pad2(70, y, lf / 60, 0xc0c0c0, 2);
        pad2(110, y, (lf % 60) * 100 / 60, 0xc0c0c0, 2);
        i = i + 1;
    }
    host::display::draw_string(8, h - 16, "LEFT TAP RUN  RIGHT TAP LAP", 0x606060, 1);
    host::display::present();
}
